'use strict';
const modules=window.CURRICULUM||[], lessons=modules.flatMap((m,mi)=>m.lessons.map((l,li)=>({...l,module:m,mi,li}))), byId=new Map(lessons.map(l=>[l.id,l]));
const STORE='gopath.v1.'+(window.studentAccount?.id||'local');
const blank=()=>({version:1,completed:[],quiz:{},notes:{},drafts:{},checks:{},projects:{},last:null});
function validate(s){if(!s||s.version!==1||!Array.isArray(s.completed)||s.completed.some(id=>!byId.has(id)))throw Error('Invalid progress file');if(new Set(s.completed).size!==s.completed.length)throw Error('Duplicate completion');if(s.last!==null&&!byId.has(s.last))throw Error('Invalid last lesson');for(const key of ['quiz','notes','drafts','checks','projects'])if(!s[key]||typeof s[key]!=='object'||Array.isArray(s[key]))throw Error('Missing '+key);for(const key of ['notes','drafts'])for(const [id,v] of Object.entries(s[key]))if(!byId.has(id)||typeof v!=='string'||v.length>200000)throw Error('Invalid text');for(const [id,v]of Object.entries(s.quiz))if(!byId.has(id)||!Number.isInteger(v)||v<0||v>=byId.get(id).quiz.options.length)throw Error('Invalid quiz');for(const [key,records]of [['checks',s.checks],['projects',s.projects]])for(const [id,record]of Object.entries(records)){const owner=key==='checks'?byId.get(id):modules.find(m=>m.id===id);if(!owner||!record||typeof record!=='object'||Array.isArray(record))throw Error('Invalid checklist');const size=key==='checks'?owner.checks.length:owner.project.rubric.length;for(const [i,value]of Object.entries(record))if(!/^\d+$/.test(i)||Number(i)>=size||typeof value!=='boolean')throw Error('Invalid checklist value')}return s}
let state;try{state=validate(window.studentAccount ? window.studentAccount.progress : JSON.parse(localStorage.getItem(STORE)))}catch{state=blank()}
let storageWarning=false;function save(){if(window.studentAccount){window.studentAccount.save(state);return}try{localStorage.setItem(STORE,JSON.stringify(state))}catch{if(!storageWarning){toast('Device storage is unavailable. Export your progress before leaving.');storageWarning=true}}}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const done=id=>state.completed.includes(id), pct=()=>Math.round(state.completed.length/Math.max(1,lessons.length)*100), modDone=m=>m.lessons.filter(l=>done(l.id)).length;
function nextLesson(){return byId.get(state.last)&&!done(state.last)?byId.get(state.last):lessons.find(l=>!done(l.id))||lessons[0]}
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.display='none',3500)}
function download(name,content,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function quizPassed(id){const l=byId.get(id);return l&&state.quiz[id]===l.quiz.answer}
function projectPassed(m){return m.project.rubric.every((_,i)=>state.projects[m.id]?.[i]===true)}
function head(kicker,title,description){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p class="intro">${description}</p></div><span class="date-chip">SELF-PACED · DOCUMENTATION-LED</span></div>`}
function moduleRow(m,i){const d=modDone(m);return `<a class="module-row ${i===nextLesson()?.mi?'current':''}" href="#module/${m.id}"><div class="module-number">${d===m.lessons.length?'✓':String(i+1).padStart(2,'0')}</div><div class="module-text"><h3>${esc(m.title)}</h3><p>${esc(m.subtitle)}</p></div><div class="row-end"><span>${d} / ${m.lessons.length} lessons</span><span class="small-arrow">↗</span></div></a>`}
function home(){const n=nextLesson(),completedProjects=modules.filter(projectPassed).length,mins=lessons.reduce((a,l)=>a+l.minutes,0);return `${head('YOUR NEXT CHAPTER','Big ideas. Small, runnable steps.','Your path from “Hello, world” to a full-stack Go application.')}<section class="hero"><div class="hero-copy"><div class="eyebrow">ONE LANGUAGE. A WORLD TO BUILD.</div><h2>Learn Go.<br>Build something that matters.</h2><p>Understand the fundamentals, connect the pieces, and turn what you learn into real applications.</p><a class="btn" href="#lesson/${n.id}">${state.completed.length?'Continue learning':'Start your journey'} <span>→</span></a></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="orbit o2"></div><div class="code-window"><div class="dots">●●● <span style="letter-spacing:0;float:right;font-size:9px">hello.go</span></div><pre><em>package</em> main\n\n<em>import</em> <b>"fmt"</b>\n\n<em>func</em> main() {\n    fmt.Println(<b>"Hello, builder."</b>)\n}</pre></div><span class="float-badge">✓ Compiled for possibility.</span></div></section><div class="stats"><div class="stat"><span class="stat-icon">↳</span><div><strong>${modules.length}</strong><small>Progressive modules</small></div></div><div class="stat"><span class="stat-icon">▤</span><div><strong>${lessons.length}</strong><small>Practical lessons</small></div></div><div class="stat"><span class="stat-icon">◇</span><div><strong>${completedProjects} / ${modules.length}</strong><small>Project reviews complete</small></div></div><div class="stat"><span class="stat-icon">◔</span><div><strong>${pct()}%</strong><small>Your path completed</small></div></div></div><div class="dashboard-grid"><div><div class="section-head"><h2>${state.completed.length?'Pick up where you left off':'Your first step'}</h2><span class="tag">${state.completed.length?'IN PROGRESS':'READY WHEN YOU ARE'}</span></div><article class="card continue"><div class="meta"><span class="tag">MODULE ${String(n.mi+1).padStart(2,'0')}</span><span>◷ ${n.minutes} min · Lesson ${n.li+1}</span></div><h3>${esc(n.title)}</h3><p>${esc(n.objectives[0])}</p><div class="progress-label"><span>${esc(n.module.title)}</span><span>${modDone(n.module)} of ${n.module.lessons.length} complete</span></div><div class="progress-track"><span style="width:${modDone(n.module)/n.module.lessons.length*100}%"></span></div><div class="continue-bottom"><span>Understand it. Try it. Make it yours.</span><a class="btn" href="#lesson/${n.id}">Open lesson →</a></div></article><div class="roadmap"><div class="section-head"><h2>A clear path forward</h2><a href="#path">Explore the curriculum →</a></div><div class="module-list">${modules.slice(0,3).map(moduleRow).join('')}</div></div></div><div class="dashboard-right"><article class="callout"><span class="tiny-label">LEARNING THAT STICKS</span><h3>You don’t need to know everything to start.</h3><p>Read a little. Write a little. Break something. Every lesson gives you a next step you can actually take.</p><a href="#projects">Meet your projects →</a></article><article class="card resource-mini"><h3>Go straight to the source ↗</h3><p>Original lessons, grounded in the documentation that Go developers use.</p><a href="https://devdocs.io/go/" target="_blank" rel="noopener">DevDocs · Go reference <span>↗</span></a><a href="https://go.dev/tour/" target="_blank" rel="noopener">A Tour of Go <span>↗</span></a><a href="https://go.dev/doc/" target="_blank" rel="noopener">Official Go documentation <span>↗</span></a><a href="#resources">Sources & coverage <span>→</span></a></article></div></div><p class="intro" style="font-size:11px;margin-top:25px">Plan for approximately ${Math.round(mins/60)} hours of guided study, plus independent exercises and project work. No prior programming experience required.</p>`}
function moduleBlock(m,i){const full=modules.find(x=>x.id===m.id)||m;return `<section class="card path-module"><div class="module-heading"><div class="module-number">${String(i+1).padStart(2,'0')}</div><div style="flex:1"><div class="meta">${esc(m.level)} · ${modDone(full)}/${full.lessons.length} complete</div><h2>${esc(m.title)}</h2><p>${esc(m.subtitle)}</p><div class="meta">Prerequisite: ${i?esc(modules[i-1].title):'None — start here'}</div></div></div>${m.lessons.map((l,j)=>`<a class="lesson-link" href="#lesson/${l.id}"><span class="check-dot">${done(l.id)?'✓':'○'}</span><span>${full.lessons.findIndex(x=>x.id===l.id)+1}. ${esc(l.title)}</span><span class="duration">${l.minutes} min →</span></a>`).join('')}<a class="lesson-link" href="#assessment/${m.id}"><span class="check-dot">◎</span>Module checkpoint<span class="duration">${full.lessons.filter(l=>quizPassed(l.id)).length}/${full.lessons.length} passed →</span></a><a class="lesson-link" href="#project/${m.id}"><span class="check-dot">◇</span>${esc(m.project.title)}<span class="duration">Project →</span></a></section>`}
function path(){return `${head('THE LEARNING PATH','From your first line to the full stack.','Twelve stages. One connected journey. Explore freely, or follow the recommended order.')}<div class="toolbar"><input id="search" type="search" placeholder="Find a lesson, topic, or skill…" aria-label="Search curriculum"><select id="filter" aria-label="Filter progress"><option value="all">All lessons</option><option value="incomplete">Still to explore</option><option value="complete">Completed</option></select></div><div id="path-results">${modules.map(moduleBlock).join('')}</div>`}
function lesson(l){state.last=l.id;save();const i=lessons.findIndex(x=>x.id===l.id);return `<div class="page-head"><div><a class="meta" href="#module/${l.module.id}">← Module ${l.mi+1} · ${esc(l.module.title)}</a><h1>${esc(l.title)}</h1><div class="meta">LESSON ${l.mi+1}.${l.li+1} <span>◷ ${l.minutes} minutes</span><span>${done(l.id)?'✓ Completed':'Learning in progress'}</span></div></div></div><div class="lesson-layout"><article class="lesson-body"><div class="eyebrow">WHAT YOU’LL BE ABLE TO DO</div><ul>${l.objectives.map(o=>`<li>${esc(o)}</li>`).join('')}</ul>${l.sections.map(s=>`<section><h2>${esc(s.title)}</h2><p>${esc(s.body)}</p></section>`).join('')}<h2>A concrete example</h2><pre><code>${esc(l.code)}</code></pre><div class="lesson-actions"><button class="quiet" data-action="copy-example">Copy example</button><button class="quiet" data-action="download-example">Download example</button></div><h2>Your turn</h2><p>${esc(l.exercise)}</p><details><summary>A nudge in the right direction</summary><p>${esc(l.hint)}</p></details><label for="code-draft" class="tiny-label">YOUR WORKSPACE · SAVED AS YOU TYPE</label><textarea class="editor" id="code-draft" spellcheck="false" aria-label="Your exercise code">${esc(state.drafts[l.id]??'// Write your exercise here.\n')}</textarea><div class="lesson-actions"><button class="quiet" data-action="download-draft">Download your code</button><a class="quiet" href="https://go.dev/play/" target="_blank" rel="noopener">Open Go Playground ↗</a></div><p class="meta">Run Go examples locally with go run, or paste into Go Playground. This browser editor saves text; it does not execute or grade Go code. Shell, SQL and multi-file examples run locally.</p><h3>Check your work</h3><div class="rubric">${l.checks.map((c,j)=>`<label><input type="checkbox" data-check="${j}" ${state.checks[l.id]?.[j]?'checked':''}>${esc(c)}</label>`).join('')}</div><details><summary>Compare with a worked solution</summary><pre><code>${esc(l.solution)}</code></pre></details>${quizMarkup(l)}<h2>Make it yours</h2><p>Explain this lesson to your future self. What surprised you? What would you try next?</p><textarea class="notes" id="lesson-note" aria-label="Lesson notes" placeholder="A thought, a question, or something to remember…">${esc(state.notes[l.id]||'')}</textarea><div class="lesson-actions"><button class="btn" data-action="complete" ${done(l.id)?'disabled':''}>${done(l.id)?'✓ Lesson complete':'Mark lesson complete ✓'}</button>${i+1<lessons.length?`<a class="btn secondary" href="#lesson/${lessons[i+1].id}">Next lesson →</a>`:`<a class="btn secondary" href="#projects">Explore projects →</a>`}</div><p class="meta">Completion requires a correct checkpoint answer and your exercise review checklist.</p></article><aside class="lesson-aside"><div class="card"><h3>In this module</h3>${l.module.lessons.map(x=>`<a href="#lesson/${x.id}" ${x.id===l.id?'aria-current="page"':''}>${done(x.id)?'✓':'○'} ${esc(x.title)}</a>`).join('')}<a href="#assessment/${l.module.id}">◎ Module checkpoint</a><a href="#project/${l.module.id}">◇ Apply it in a project</a></div><div class="card"><h3>Read the original sources</h3>${l.sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)} ↗</a>`).join('')}<a href="https://devdocs.io/go/" target="_blank" rel="noopener">DevDocs Go reference ↗</a><p>References explain the contract. Your experiments make it click.</p></div></aside></div>`}
function quizMarkup(l){const selected=state.quiz[l.id];return `<form class="quiz" data-quiz="${l.id}"><h3>Check your understanding</h3><p>${esc(l.quiz.question)}</p>${l.quiz.options.map((o,j)=>`<label><input type="radio" name="answer-${l.id}" value="${j}" ${selected===j?'checked':''} required>${esc(o)}</label>`).join('')}<button class="btn" type="submit">Check answer →</button><div class="feedback" role="status">${selected===undefined?'':`${quizPassed(l.id)?'✓ Correct.':'Try again.'} ${esc(l.quiz.explanation)}`}</div></form>`}
function assessment(m){const score=m.lessons.filter(l=>quizPassed(l.id)).length;return `${head('MODULE CHECKPOINT',esc(m.title),'Use these questions to find what is solid and what needs another pass. You can retry anytime.')}<article class="lesson-body"><div class="assessment-score">${score} / ${m.lessons.length}</div><p>Correct answers saved. Pass all questions, then demonstrate the ideas in the module project.</p>${m.lessons.map(l=>`${quizMarkup(l)}<a class="meta" href="#lesson/${l.id}">Revisit: ${esc(l.title)} →</a>`).join('')}<a class="btn" href="#project/${m.id}">Take it into a project →</a></article>`}
function projects(){return `${head('BUILD TO UNDERSTAND','Your ideas, made real.','A project at every stage. A full-stack application at the finish line.')}<div class="notice">Projects are reviewed against a self-assessment rubric. Checking a rubric records your review; it is not an automated code evaluation.</div><div class="project-grid">${modules.map((m,i)=>`<article class="card project-card"><div class="meta"><span class="tag">PROJECT ${String(i+1).padStart(2,'0')}</span><span>${esc(m.level)}</span></div><h3>${esc(m.project.title)}</h3><p>${esc(m.project.brief)}</p><div class="meta">${projectPassed(m)?'✓ Review complete':`${m.project.rubric.filter((_,j)=>state.projects[m.id]?.[j]).length}/${m.project.rubric.length} review criteria met`}</div><a class="btn secondary" href="#project/${m.id}">Open project brief →</a></article>`).join('')}</div>`}
function project(m){return `${head('PROJECT '+String(modules.indexOf(m)+1).padStart(2,'0'),esc(m.project.title),esc(m.project.brief))}<article class="lesson-body project-detail"><h2>What you’ll build</h2><ol>${m.project.requirements.map(r=>`<li>${esc(r)}</li>`).join('')}</ol><h2>Review your work</h2><p>Test the happy path and the failure cases. Check each item only after you can demonstrate it.</p><div class="rubric">${m.project.rubric.map((r,j)=>`<label><input type="checkbox" data-project="${m.id}" data-index="${j}" ${state.projects[m.id]?.[j]?'checked':''}>${esc(r)}</label>`).join('')}</div><h2>A practical workflow</h2><ol><li>Sketch the inputs, outputs and failure cases before writing code.</li><li>Build the smallest working path. Add one behavior at a time.</li><li>Write a regression test for each bug you fix.</li><li>Review the source documentation and record your tradeoffs in a README.</li></ol><pre>go fmt ./...\ngo vet ./...\ngo test ./...\ngo test -race ./...</pre><p>Race detection needs a supported platform and a C compiler. Integration tests need the database or services described in your project.</p><a class="btn" href="#assessment/${m.id}">Review the module checkpoint →</a></article>`}
function notes(){const entries=lessons.filter(l=>state.notes[l.id]?.trim());return `${head('YOUR NOTEBOOK','Keep the things that click.','Your notes stay with your learning progress. Export a backup whenever you need one.')}${entries.length?entries.map(l=>`<article class="card note-card"><a href="#lesson/${l.id}">${esc(l.title)} ↗</a><p>${esc(state.notes[l.id])}</p></article>`).join(''):'<div class="card empty">Your notebook starts with a thought.<br>Add a note at the end of any lesson.</div>'}<div class="page-tools"><button class="btn secondary" data-action="import">Import progress</button><button class="quiet" data-action="reset">Reset this device’s progress</button></div>`}
function resources(){const unique=[...new Map(lessons.flatMap(l=>l.sources).map(s=>[s.url,s])).values()];return `${head('DOCUMENTATION & COVERAGE','Learn with the source beside you.','Use DevDocs for quick lookup and the official references for the precise behavior.')}<div class="notice">Reviewed November 3, 2026. The curriculum covers the core language and a practical full-stack path; it is not an exhaustive review of every standard-library symbol. DevDocs may track a different Go version. Follow each API’s version notes and install a supported Go toolchain.</div><div class="sources-grid"><article class="card source-card"><h2>The documentation map</h2><a href="#reference">Explore all 6,590 indexed entries →</a><p>Language syntax and semantics → fundamentals and types.<br>fmt, strings, slices, maps, io, os, encoding/json → everyday programs.<br>testing, fuzzing, sync, context → dependable software.<br>net/http, html/template, database/sql → the web stack.<br>Modules, diagnostics, security and tool commands → shipping and maintenance.</p><a href="https://devdocs.io/go/" target="_blank" rel="noopener">Open DevDocs Go ↗</a></article><article class="card source-card"><h2>A coherent stack</h2><p>The learning app uses HTML, CSS and JavaScript with browser-local progress. Your course projects use Go’s standard library, PostgreSQL, server-rendered HTML and browser fetch. Learn the HTTP and data contracts before adding frameworks.</p><p>Code drafts, notes, quiz answers and review checklists are stored on this device. No account or cross-device sync. Export and import a backup to move them.</p></article><article class="card source-card"><h2>Further reference tracks</h2><p>After the core path: archive/compress, crypto internals, debug, go/ast, go/parser, image, math, net/rpc, plugin, reflect, runtime, syscall and unsafe. These are specialist references, not beginner prerequisites.</p><a href="https://pkg.go.dev/std" target="_blank" rel="noopener">Browse the standard library ↗</a></article><article class="card source-card"><h2>Source audit</h2><p>The linked topics shape the learning sequence. Full-stack extensions also use PostgreSQL and MDN documentation. Original exercises and projects connect those references into a practical course.</p><a href="sources.json" target="_blank">Download the topic and source map ↗</a><br><a href="course-guide.md" download>Download the complete course guide ↓</a></article>${unique.map(s=>`<article class="card source-card"><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)} ↗</a><p>${esc(new URL(s.url).hostname)}</p></article>`).join('')}</div>`}
let referenceData=null;
function reference(){return head('THE COMPLETE INDEX','A reference for the road ahead.','Search every entry in the retrieved DevDocs Go index. Use this as a lookup companion to your lessons.')+'<div class="notice">6,590 indexed entries across 64 topic families. This inventory includes internal and experimental topics. An index entry is not a recommendation to use an API, and may differ from your installed Go version.</div><div class="toolbar"><input type="search" id="ref-search" aria-label="Search documentation entries" placeholder="Search a package or symbol…"><select id="ref-topic" aria-label="Documentation topic"><option value="">All topic families</option></select></div><div id="ref-results" class="module-list">Loading the reference index…</div>'}
async function loadReference(){try{referenceData??=await(await fetch('devdocs-index.json')).json();const select=document.querySelector('#ref-topic');if(!select)return;select.innerHTML='<option value="">All topic families</option>'+referenceData.types.map(t=>'<option value="'+esc(t.name)+'">'+esc(t.name)+' ('+t.count+')</option>').join('');filterReference()}catch{const target=document.querySelector('#ref-results');if(target)target.textContent='The index could not load. Open DevDocs directly from Documentation.'}}
function filterReference(){if(!referenceData)return;const query=document.querySelector('#ref-search')?.value.toLowerCase()||'',topic=document.querySelector('#ref-topic')?.value;const entries=referenceData.entries.filter(e=>(!topic||e.type===topic)&&e.name.toLowerCase().includes(query));document.querySelector('#ref-results').innerHTML='<p class="meta">'+entries.length+' matches · showing up to 100. Narrow your search to find more.</p>'+entries.slice(0,100).map(e=>'<article class="module-row"><div class="module-text"><h3>'+esc(e.name)+'</h3><p>'+esc(e.type)+'</p></div><a class="quiet" href="https://devdocs.io/go/'+esc(e.path)+'" target="_blank" rel="noopener">DevDocs ↗</a><a class="quiet" href="https://pkg.go.dev/'+esc(e.path.replace('/index',''))+'" target="_blank" rel="noopener">Official ↗</a></article>').join('')}
function render(){const [rawView,id]=location.hash.slice(1).split('/'),view=rawView||'home', main=document.querySelector('main');let html,nav=view;switch(view){case'home':html=home();break;case'path':html=path();break;case'module':{const m=modules.find(m=>m.id===id);html=m?`${head('THE LEARNING PATH',esc(m.title),esc(m.subtitle))}${moduleBlock(m,modules.indexOf(m))}`:null;nav='path';break}case'lesson':html=byId.has(id)?lesson(byId.get(id)):null;nav='path';break;case'assessment':{const m=modules.find(m=>m.id===id);html=m?assessment(m):null;nav='path';break}case'projects':html=projects();break;case'project':{const m=modules.find(m=>m.id===id);html=m?project(m):null;nav='projects';break}case'notes':html=notes();break;case'resources':html=resources();break;case'reference':html=reference();nav='resources';break}main.innerHTML=html??`${head('PAGE NOT FOUND','Let’s get you back on the path.','This lesson or page is not available.')}<a class="btn" href="#path">Open curriculum →</a>`;document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===nav));document.querySelector('#breadcrumb').textContent='Your workspace / '+({home:'Overview',path:'Learning path',projects:'Projects',notes:'My notebook',resources:'Documentation'}[nav]||'Learning path');document.title=(view==='lesson'&&byId.has(id)?byId.get(id).title:'Learn by building')+' · Go Path';window.scrollTo(0,0);if(view==='reference')loadReference()}
window.addEventListener('hashchange',render);
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();document.querySelector('main').focus()});
document.addEventListener('submit',e=>{const form=e.target.closest('[data-quiz]');if(!form)return;e.preventDefault();const l=byId.get(form.dataset.quiz),selected=form.querySelector('input:checked');if(!selected)return;state.quiz[l.id]=Number(selected.value);save();const score=document.querySelector('.assessment-score');if(score)score.textContent=l.module.lessons.filter(item=>quizPassed(item.id)).length+' / '+l.module.lessons.length;form.querySelector('.feedback').textContent=`${quizPassed(l.id)?'✓ Correct.':'Try again.'} ${l.quiz.explanation}`;toast(quizPassed(l.id)?'Checkpoint passed.':'One more look — you can retry.');});
document.addEventListener('input',e=>{const id=location.hash.split('/')[1];if(e.target.id==='lesson-note'){state.notes[id]=e.target.value;save()}if(e.target.id==='code-draft'){state.drafts[id]=e.target.value;save()}if(e.target.id==='search')filterPath();if(e.target.id==='ref-search')filterReference()});
document.addEventListener('change',e=>{const id=location.hash.split('/')[1];if(e.target.dataset.check!==undefined){state.checks[id]??={};state.checks[id][e.target.dataset.check]=e.target.checked;save()}if(e.target.dataset.project){const mid=e.target.dataset.project;state.projects[mid]??={};state.projects[mid][e.target.dataset.index]=e.target.checked;save();toast('Project review saved.')}if(e.target.id==='filter')filterPath();if(e.target.id==='ref-topic')filterReference()});
function filterPath(){const query=document.querySelector('#search').value.toLowerCase(),filter=document.querySelector('#filter').value;const matches=modules.map((m,i)=>{const ls=m.lessons.filter(l=>(`${m.title} ${m.subtitle} ${l.title} ${l.objectives.join(' ')}`.toLowerCase().includes(query))&&(filter==='all'||done(l.id)===(filter==='complete')));return ls.length?moduleBlock({...m,lessons:ls},i):''}).join('');document.querySelector('#path-results').innerHTML=matches||'<div class="empty">No lessons found. Try a broader search.</div>'}
document.addEventListener('click',async e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;const id=location.hash.split('/')[1],l=byId.get(id);if(action==='copy-example'){try{await navigator.clipboard.writeText(l.code);toast('Example copied.')}catch{toast('Select the example text and copy it.')}}if(action==='download-example')download(l.id+'-example.txt',l.code,'text/plain');if(action==='download-draft')download(l.id+'.go',state.drafts[id]||'','text/plain');if(action==='complete'){if(!quizPassed(id))return toast('Pass the checkpoint question first.');if(!l.checks.every((_,j)=>state.checks[id]?.[j]===true))return toast('Review every exercise criterion first.');if(!done(id))state.completed.push(id);save();render();toast('Lesson complete. One step further.')}if(action==='import')document.querySelector('#import-file').click();if(action==='reset'&&confirm('Reset all progress, code drafts and notes on this device? Export a backup first if you want to keep them.')){state=blank();save();render();toast('Progress reset.')}});
document.querySelector('#export').onclick=()=>download('go-path-progress.json',JSON.stringify(state,null,2));
document.querySelector('#import-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2000000)throw Error('File too large');const imported=validate(JSON.parse(await f.text()));if(confirm('Replace progress, drafts and notes on this device with this backup?')){state=imported;save();render();toast('Your learning space has been restored.')}}catch{toast('That is not a valid Go Path progress backup.')}e.target.value=''};
render();


